logs.fixedScript:
updateField(processData, 'leaveBalanceUpdated', true);
updateField(processData, 'teamCalendarUpdated', getCurrentDate());
addToArray(processData, 'approvalHistory', {
  action: 'approved',
  timestamp: getCurrentDate(),
  approvedBy: getField(processData, 'completedBy'),
  comments: getField(processData, 'formData.comments') || ''
});
log('Leave balance updated, team calendar synchronized, and approval logged');

// Check if customer already exists by email
const existingCustomer = getField(processData, 'email');
if (existingCustomer) {
  // Create customer profile from processData
  const customerProfile = {
    id: formatString('customer_{timestamp}', { timestamp: Date.now() }),
    firstName: getField(processData, 'firstName'),
    lastName: getField(processData, 'lastName'),
    email: getField(processData, 'email'),
    phone: getField(processData, 'phone'),
    companyName: getField(processData, 'companyName'),
    customerCategory: getField(processData, 'customerCategory'),
    profileCreated: getCurrentDate(),
    interactionHistory: [
      {
        type: 'registration',
        date: getCurrentDate(),
        initiator: getField(processData, 'initiator'),
        message: getField(processData, 'message')
      }
    ]
  };

  log('Customer profile created:', customerProfile);
  return customerProfile;
} else {
  log('Error: Customer email not found in processData');
  return null;
}

// Check for conflicts with existing team leaves, project deadlines, and milestones
const teamMember = getField(processData, 'formData.employeeName') || 'Unknown';
const startDate = getField(processData, 'formData.startDate') || getField(processData, 'startDate');
const endDate = getField(processData, 'formData.endDate') || getField(processData, 'endDate');
const leaveType = getField(processData, 'formData.leaveType') || getField(processData, 'leaveType');
const totalDays = getField(processData, 'formData.totalDays');

// Create date range object
const dateRange = {
  start: startDate,
  end: endDate,
  totalDays: totalDays
};

// Initialize conflicts array
let conflicts = [];

// Check for weekend conflicts
const startDateObj = new Date(startDate);
const endDateObj = new Date(endDate);
const dayOfWeek = startDateObj.getDay();
if (dayOfWeek === 0 || dayOfWeek === 6) {
  addToArray(conflicts, 'conflicts', {
    type: 'weekend',
    message: 'Leave request includes weekend days',
    severity: 'low'
  });
}

// Check for holiday conflicts (basic check for common holidays)
const currentDate = getCurrentDate();
const currentYear = new Date(currentDate).getFullYear();
const holidays = [
  `${currentYear}-01-01`, // New Year
  `${currentYear}-12-25`, // Christmas
  `${currentYear}-07-04`  // Independence Day
];

holidays.forEach(holiday => {
  if (startDate <= holiday && endDate >= holiday) {
    addToArray(conflicts, 'conflicts', {
      type: 'holiday',
      message: `Leave overlaps with holiday: ${holiday}`,
      severity: 'medium'
    });
  }
});

// Check for minimum notice period
const requestDate = new Date(getField(processData, 'startTime') || getCurrentDate());
const leaveStartDate = new Date(startDate);
const daysDifference = Math.ceil((leaveStartDate - requestDate) / (1000 * 60 * 60 * 24));

if (daysDifference < 7 && leaveType !== 'Medical Leave') {
  addToArray(conflicts, 'conflicts', {
    type: 'notice',
    message: 'Insufficient notice period (less than 7 days)',
    severity: 'high'
  });
}

// Check available balance
const availableBalance = getField(processData, 'availableBalance') || 0;
if (totalDays > availableBalance) {
  addToArray(conflicts, 'conflicts', {
    type: 'balance',
    message: `Insufficient leave balance. Requested: ${totalDays}, Available: ${availableBalance}`,
    severity: 'high'
  });
}

// Create result object
const result = {
  teamMember: teamMember,
  dateRange: dateRange,
  leaveType: leaveType,
  conflicts: getField(conflicts, 'conflicts') || [],
  hasConflicts: (getField(conflicts, 'conflicts') || []).length > 0,
  conflictSummary: formatString('Found {count} potential conflicts for {member}', {
    count: (getField(conflicts, 'conflicts') || []).length,
    member: teamMember
  }),
  checkDate: getCurrentDate(),
  status: (getField(conflicts, 'conflicts') || []).some(c => c.severity === 'high') ? 'blocked' : 'approved'
};

log('Conflict check completed for:', teamMember, 'Result:', result.status);

result

